-- ---------------------------------------------------------------------------------------------------------------------
-- course_questions 1..6 — visible 1, 2, 3, 6 (1 resolved) · deleted 5 (by the asker) · hidden 4 (admin, BR-35).
-- lesson_id, when set, belongs to the enrollment's course (BR-37 trigger); 3 and 4 are course-level questions.
-- ---------------------------------------------------------------------------------------------------------------------
INSERT INTO course_questions (id, enrollment_id, lesson_id, title, content, is_resolved, visibility_status,
                              moderated_by, moderated_at, created_at, updated_at) VALUES
    (1, 1, 5,    'Khác nhau giữa scope singleton và prototype?',
        'Em chưa rõ khi nào nên dùng scope prototype thay cho singleton mặc định. Thầy có thể cho ví dụ thực tế không ạ?',
        TRUE,  'visible', NULL, NULL,                  '2026-09-20 20:00:00', '2026-09-21 12:00:00'),
    (2, 1, 8,    'Lỗi Communications link failure khi kết nối MySQL',
        'Em chạy ứng dụng thì gặp lỗi Communications link failure, MySQL đã bật bằng Docker. Em cần kiểm tra gì ạ?',
        FALSE, 'visible', NULL, NULL,                  '2026-10-28 21:00:00', '2026-10-28 21:00:00'),
    (3, 4, NULL, 'Khóa học có cập nhật lên React 19 không?',
        'Em thấy React 19 đã ra mắt, khóa học có kế hoạch cập nhật các bài học theo phiên bản mới không ạ?',
        FALSE, 'visible', NULL, NULL,                  '2026-10-14 20:00:00', '2026-10-14 20:00:00'),
    (4, 9, NULL, 'Bán tài khoản khóa học giá rẻ',
        'Ai cần tài khoản học chung giá rẻ thì nhắn tin cho mình nhé.',
        FALSE, 'hidden',  1,    '2026-10-10 10:30:00', '2026-10-09 22:05:00', '2026-10-10 10:30:00'),
    (5, 3, 26,   'Hàm dropna xóa mất quá nhiều dữ liệu',
        'Sau khi gọi dropna thì dữ liệu của em chỉ còn một nửa, có cách nào giữ lại các dòng chỉ thiếu một cột không ạ?',
        FALSE, 'deleted', NULL, NULL,                  '2026-09-15 20:00:00', '2026-09-15 20:30:00'),
    (6, 5, 42,   'Nên chọn đối tượng quảng cáo rộng hay hẹp?',
        'Với ngân sách 200.000 đ mỗi ngày thì nên nhắm đối tượng rộng để thuật toán tự tối ưu hay khoanh vùng hẹp ạ?',
        FALSE, 'visible', NULL, NULL,                  '2026-10-15 20:00:00', '2026-10-15 20:00:00');

-- ---------------------------------------------------------------------------------------------------------------------
-- question_answers 1..7 — instructor answers by the main instructor (1, 6) and an accepted co-instructor (3, user 3
-- on course 1); student follow-ups by the asker (2, 4) · deleted 5 (by its author) · hidden 7 (admin, BR-35).
-- ---------------------------------------------------------------------------------------------------------------------
INSERT INTO question_answers (id, question_id, author_id, author_type, content, visibility_status, moderated_by,
                              moderated_at, created_at, updated_at) VALUES
    (1, 1, 2, 'instructor',
        'Singleton dùng chung một đối tượng cho cả ứng dụng, phù hợp với service không giữ trạng thái. Prototype tạo đối tượng mới mỗi lần inject, dùng khi bean giữ trạng thái riêng, ví dụ một builder báo cáo.',
        'visible', NULL, NULL, '2026-09-21 08:00:00', '2026-09-21 08:00:00'),
    (2, 1, 6, 'student',
        'Em hiểu rồi ạ, em đã thử với builder báo cáo và chạy đúng. Cảm ơn thầy!',
        'visible', NULL, NULL, '2026-09-21 12:00:00', '2026-09-21 12:00:00'),
    (3, 2, 3, 'instructor',
        'Em kiểm tra cổng 3306 đã mở chưa và URL kết nối dùng localhost hay tên service của Docker Compose nhé. Nếu ứng dụng chạy ngoài Docker thì phải dùng localhost.',
        'visible', NULL, NULL, '2026-10-29 09:00:00', '2026-10-29 09:00:00'),
    (4, 2, 6, 'student',
        'Em đổi sang localhost thì hết lỗi kết nối, nhưng giờ lại báo sai mật khẩu ạ.',
        'visible', NULL, NULL, '2026-10-29 20:00:00', '2026-10-29 20:00:00'),
    (5, 2, 6, 'student',
        'Em gửi nhầm câu trả lời.',
        'deleted', NULL, NULL, '2026-10-29 20:05:00', '2026-10-29 20:06:00'),
    (6, 6, 4, 'instructor',
        'Với ngân sách đó em nên bắt đầu với đối tượng rộng vừa phải, chạy 3–5 ngày để thuật toán học rồi mới thu hẹp theo dữ liệu chuyển đổi.',
        'visible', NULL, NULL, '2026-10-16 09:00:00', '2026-10-16 09:00:00'),
    (7, 6, 9, 'student',
        'Thầy dạy chán quá, ai cần tài liệu lậu thì inbox mình.',
        'hidden',  1,    '2026-10-17 08:00:00', '2026-10-16 21:00:00', '2026-10-17 08:00:00');

